  CONSTRAINT `fk_paex_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_paex_extrajudicial` FOREIGN KEY (`processo_extrajudicial_id`) REFERENCES `processos_extrajudiciais` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
