--
-- Table structure for table `processos_extrajudiciais`
--

DROP TABLE IF EXISTS `processos_extrajudiciais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processos_extrajudiciais` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `protocolo` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Numero na instituicao de origem, ex.: SIMP 000123-001/2026',
  `data_expediente` date NOT NULL,
  `instituicao_externa_id` smallint unsigned NOT NULL,
  `orgao_externo_id` smallint unsigned DEFAULT NULL,
  `assunto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descricao` text COLLATE utf8mb4_unicode_ci,
  `situacao` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EM_ANDAMENTO' COMMENT 'EM_ANDAMENTO | PENDENTE_RESPOSTA | RESPONDIDO | ARQUIVADO | OUTRA',
  `observacoes` text COLLATE utf8mb4_unicode_ci,
  `criado_por` int unsigned DEFAULT NULL,
  `atualizado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pe_protocolo` (`instituicao_externa_id`,`protocolo`),
  KEY `ix_pe_protocolo` (`protocolo`),
  KEY `ix_pe_data` (`data_expediente`),
  KEY `ix_pe_orgao` (`orgao_externo_id`),
  KEY `ix_pe_situacao` (`situacao`),
  KEY `fk_pe_criado_por` (`criado_por`),
  KEY `fk_pe_atualizado_por` (`atualizado_por`),
  CONSTRAINT `fk_pe_atualizado_por` FOREIGN KEY (`atualizado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pe_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pe_instituicao` FOREIGN KEY (`instituicao_externa_id`) REFERENCES `instituicoes_externas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pe_orgao` FOREIGN KEY (`orgao_externo_id`) REFERENCES `orgaos_externos` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `processos_extrajudiciais`
--

LOCK TABLES `processos_extrajudiciais` WRITE;
/*!40000 ALTER TABLE `processos_extrajudiciais` DISABLE KEYS */;
