--
-- Table structure for table `processos_judiciais`
--

DROP TABLE IF EXISTS `processos_judiciais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processos_judiciais` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `numero_cnj` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ex.: 1008695-17.2026.8.11.0006',
  `tribunal` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orgao_julgador` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cargo_judicial` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ex.: Juiz Titular',
  `competencia` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Competencia do orgao julgador',
  `jurisdicao` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `classe_judicial` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `classe_codigo` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Codigo CNJ da classe, ex.: 156',
  `classe_abreviada` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sigla da classe no cabecalho do PJe, ex.: ProceComCiv',
  `assunto_principal` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resumo_partes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Resumo "Polo ativo X Polo passivo" do cabecalho',
  `data_autuacao` date DEFAULT NULL COMMENT 'Autuacao original (distinta da ultima distribuicao)',
  `data_distribuicao` date DEFAULT NULL,
  `valor_causa` decimal(15,2) DEFAULT NULL,
  `situacao` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segredo_justica` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `justica_gratuita` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `tutela_liminar` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `prioridade` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `prioridade_descricao` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Motivo da prioridade, ex.: Idoso',
  `resumo` text COLLATE utf8mb4_unicode_ci,
  `observacoes` text COLLATE utf8mb4_unicode_ci,
  `origem` enum('MANUAL','PJE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `url_origem` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
