CREATE TABLE `sigtap_procedimentos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `codigo` char(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Somente digitos, ex.: 0301010072',
  `nome` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Descricao oficial do procedimento',
  `grupo_codigo` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `grupo_nome` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subgrupo_codigo` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subgrupo_nome` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `forma_organizacao_codigo` char(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `forma_organizacao_nome` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `competencia` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AAAAMM da tabela oficial importada; NULL = cadastro manual',
  `origem` enum('MANUAL','SIGTAP') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `criado_por` int unsigned DEFAULT NULL,
  `atualizado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sigtap_codigo` (`codigo`),
  KEY `ix_sigtap_nome` (`nome`),
  KEY `ix_sigtap_estrutura` (`grupo_codigo`,`subgrupo_codigo`,`forma_organizacao_codigo`),
  KEY `fk_sigtap_criado_por` (`criado_por`),
  KEY `fk_sigtap_atualizado_por` (`atualizado_por`),
  CONSTRAINT `fk_sigtap_atualizado_por` FOREIGN KEY (`atualizado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sigtap_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_sigtap_ativo` CHECK ((`ativo` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
